cat > /tmp/qzone/enc <<'SH'
#!/bin/bash
run(){ /workspace/dataset/test12_executable --a "$1" --b B --c C --d D 2>/dev/null; }
printf '%-6s | %-14s | %-14s | %-14s | %-14s\n' CHAR mainKEY mainVAL fragKEY fragVAL
while IFS= read -r ch; do
  o1=$(run "http://h/p?a${ch}b" | sed -n 4p); o1=${o1#http://h/p?}
  o2=$(run "http://h/p?k=a${ch}b" | sed -n 4p); o2=${o2#http://h/p?}; o2=${o2%%#*}
  o1=${o1%%#*}
  o3=$(run "http://h/p#zz?a${ch}b=1" | sed -n 1p)
  o4=$(run "http://h/p#zz?k=a${ch}b" | sed -n 1p)
  printf '%-6q | %-14s | %-14s | %-14s | %-14s\n' "$ch" "$o1" "$o2" "$o3" "$o4"
done < /tmp/punct.txt
SH
chmod +x /tmp/qzone/enc; /tmp/qzone/enc

cat > /tmp/qzone/sweep <<'SH'
#!/bin/bash
run(){ /workspace/dataset/test12_executable --a "$1" --b B --c C --d D 2>/dev/null; }
for i in $(seq 1 127); do
  ch=$(printf "\\$(printf '%03o' $i)")
  o=$(run "http://h/p?k=a${ch}b" | sed -n 4p); o=${o#http://h/p?k=}; o=${o%%#*}
  if [ "$o" != "a${ch}b" ]; then printf '%3d %-4q -> %s\n' "$i" "$ch" "$o"; fi
done
SH
chmod +x /tmp/qzone/sweep; /tmp/qzone/sweep 2>&1 | head -80

R4(){ /workspace/dataset/test12_executable --a "$1" --b B --c C --d D 2>&1 | sed -n 4p; }
R1(){ /workspace/dataset/test12_executable --a "$1" --b B --c C --d D 2>&1 | sed -n 1p; }
for q in "a%3Db=1" "a%26b=1" "a%3Fb=c" "a=b%26c" "a=b%3Dc" "%41%3D%42=1" "=" "==" "a==b" "a=1&=2&=&3" "&&" "&&&" "a&&" "%=1" "k=%2B%2B" "k=+ +" "a+b=c+d" "%20=%20" "0=0" "K=V"; do printf '%-16q -> L4=%-40q L1=%q\n' "$q" "$(R4 "http://h/p?$q")" "$(R1 "http://h/p#zz?$q")"; done

cat > /tmp/qzone/enc2 <<'SH'
